source = '''from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and
                            p not in seen and grid[p[0]][p[1]] != 0):
                        seen.add(p)
                        q.append(p)
            components.append(comp)

    panel_cells = max(components, key=len)
    top = min(r for r, c in panel_cells)
    bottom = max(r for r, c in panel_cells)
    left = min(c for r, c in panel_cells)
    right = max(c for r, c in panel_cells)
    panel = [row[left:right + 1] for row in grid[top:bottom + 1]]
    ph, pw = len(panel), len(panel[0])
    panel_positions = {(r + top, c + left) for r, row in enumerate(panel)
                       for c, value in enumerate(row) if value != 0}

    counts = Counter(value for row in panel for value in row if value not in (0, 1))
    outside = {}
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value not in (0, 1) and (r, c) not in panel_positions:
                outside.setdefault(value, []).append((r, c))
    anchors = {}
    for color, count in counts.items():
        if count == 1 and len(outside.get(color, [])) == 1:
            for r, row in enumerate(panel):
                for c, value in enumerate(row):
                    if value == color:
                        anchors[color] = (r, c)
                        break

    points = [(color, cells[0]) for color, cells in outside.items()
              if color in anchors and len(cells) == 1]
    elbow = None
    for color, (r, c) in points:
        others = [p for other_color, p in points if other_color != color]
        if len(others) == 2:
            a, b = others
            if (a[0] == r and b[1] == c) or (b[0] == r and a[1] == c):
                elbow = (color, (r, c))
                break
    elbow_color, (er, ec) = elbow
    horizontal = next(p for color, p in points if color != elbow_color and p[0] == er)
    vertical = next(p for color, p in points if color != elbow_color and p[1] == ec)
    elbow_row = 'T' if vertical[0] > er else 'B'
    elbow_col = 'L' if horizontal[1] > ec else 'R'
    opposite_row = 'B' if elbow_row == 'T' else 'T'
    opposite_col = 'R' if elbow_col == 'L' else 'L'
    targets = {elbow_color: (elbow_row, elbow_col)}
    for color, p in points:
        if color == elbow_color:
            continue
        if p[0] == er:
            targets[color] = (elbow_row, opposite_col)
        else:
            targets[color] = (opposite_row, elbow_col)

    transforms = [
        (lambda r, c: (r, c), ph, pw),
        (lambda r, c: (ph - 1 - r, c), ph, pw),
        (lambda r, c: (r, pw - 1 - c), ph, pw),
        (lambda r, c: (ph - 1 - r, pw - 1 - c), ph, pw),
        (lambda r, c: (c, r), pw, ph),
        (lambda r, c: (pw - 1 - c, ph - 1 - r), pw, ph),
        (lambda r, c: (c, ph - 1 - r), pw, ph),
        (lambda r, c: (pw - 1 - c, r), pw, ph),
    ]

    def corner(role, oh, ow):
        row, col = role
        return (1 if row == 'T' else oh - 2,
                1 if col == 'L' else ow - 2)

    selected = None
    for mapping, oh, ow in transforms:
        if all(mapping(*anchors[color]) == corner(targets[color], oh, ow)
               for color in anchors):
            selected = (mapping, oh, ow)
            break
    mapping, oh, ow = selected
    out = [[1] * ow for _ in range(oh)]
    for r in range(ph):
        for c in range(pw):
            y, x = mapping(r, c)
            out[y][x] = panel[r][c]
    return out
